"""Command-line handling for the journal application."""
import os
import sys
import pwd

DESCRIPTION = 'Tui app allows writing and managing journals/notes from within the terminal With different local back-ends'
DESCRIPTIONS = {
    'print-config': 'Print the current settings including the paths for the back-end files',
    'import-journals': 'Import journals from the given transfer JSON file to the current back-end file',
    'assign-priority': 'Assign priority for all the entries with empty priority field',
    'theme': 'Provides commands regarding changing themes and styles of the app',
    'print-path': 'Prints the path to the user themes file',
    'print-default': 'Dumps the styles with the default values to be used as a reference and base for user custom themes',
    'write-defaults': "Creates user custom themes file if doesn't exist then writes the default styles to it",
    'help': 'Print this message or the help of the given subcommand(s)',
}
ALIASES = {'pc': 'print-config', 'imj': 'import-journals', 'ap': 'assign-priority', 'style': 'theme'}
THEME_ALIASES = {'path': 'print-path', 'default': 'print-default', 'write': 'write-defaults'}
OPTION_NAMES = {'j': '--json-file-path <FILE PATH>', 's': '--sqlite-file-path <FILE PATH>',
                'b': '--backend-type <BACKEND_TYPE>', 'c': '--config <DIR PATH>',
                'l': '--log <FILE PATH>', 'p': '--path <FILE PATH>'}
LONGS = {'--json-file-path': 'j', '--sqlite-file-path': 's', '--backend-type': 'b',
         '--config': 'c', '--log': 'l', '--path': 'p', '--verbose': 'v',
         '--help': 'h', '--version': 'V'}


def home():
    return os.environ.get('HOME') or pwd.getpwuid(os.getuid()).pw_dir


def xdg(name, fallback):
    p = os.environ.get(name, '')
    return p if p.startswith('/') else os.path.join(home(), fallback)


def config_dir():
    return os.path.join(xdg('XDG_CONFIG_HOME', '.config'), 'tui-journal')


def log_path():
    return os.path.join(xdg('XDG_CACHE_HOME', '.cache'), 'tui-journal', 'tui-journal.log')


def usage(context=''):
    return 'executable' + {
        '': ' [OPTIONS] [COMMAND]',
        'print-config': ' print-config',
        'import-journals': ' import-journals --path <FILE PATH>',
        'assign-priority': ' assign-priority <PRIORITY>',
        'theme': ' theme <COMMAND>',
        'theme print-path': ' theme print-path',
        'theme print-default': ' theme print-default',
        'theme write-defaults': ' theme write-defaults',
        'help': ' help [COMMAND]...',
        'theme help': ' theme help [COMMAND]...',
    }.get(context, ' ' + context)


def help_text(context=''):
    if not context:
        return f'''{DESCRIPTION}

Usage: {usage()}

Commands:
  print-config     {DESCRIPTIONS['print-config']} [aliases: pc]
  import-journals  {DESCRIPTIONS['import-journals']} [aliases: imj]
  assign-priority  {DESCRIPTIONS['assign-priority']} [aliases: ap]
  theme            {DESCRIPTIONS['theme']} [aliases: style]
  help             {DESCRIPTIONS['help']}

Options:
  -j, --json-file-path <FILE PATH>    Sets the entries Json file path and starts using it
  -s, --sqlite-file-path <FILE PATH>  Sets the entries sqlite file path and starts using it
  -b, --backend-type <BACKEND_TYPE>   Sets the backend type and starts using it [possible values: json, sqlite]
  -c, --config <DIR PATH>             Specifies the path for the configuration directory.
                                      Configuration files is considered as root for themes file too.
                                      It still accepts the path for configuration file for backward compatibility.
                                      (default path: {config_dir()})
  -v, --verbose...                    Increases logging verbosity each use for up to 3 times
  -l, --log <FILE PATH>               Specifies a file to use for logging
                                      (default file: {log_path()})
  -h, --help                          Print help
  -V, --version                       Print version
'''
    name = context.split()[-1]
    text = DESCRIPTIONS[name] + '\n\nUsage: ' + usage(context) + '\n'
    if context == 'theme':
        text += f'''
Commands:
  print-path      {DESCRIPTIONS['print-path']} [aliases: path]
  print-default   {DESCRIPTIONS['print-default']} [aliases: default]
  write-defaults  {DESCRIPTIONS['write-defaults']} [aliases: write]
  help            {DESCRIPTIONS['help']}
'''
    if name == 'help':
        return text + '\nArguments:\n  [COMMAND]...  Print help for the subcommand(s)\n'
    if context == 'assign-priority':
        text += '\nArguments:\n  <PRIORITY>  Priority value (Positive number)\n'
    text += '\nOptions:\n'
    if context == 'import-journals':
        text += '  -p, --path <FILE PATH>  Path of the JSON file to import from\n  -h, --help              Print help\n'
    else:
        text += '  -h, --help  Print help\n'
    return text


def error(message, context=None, tip=None):
    s = 'error: ' + message + '\n'
    if tip:
        s += '\n  tip: ' + tip + '\n'
    if context is not None:
        s += '\nUsage: ' + usage(context) + '\n'
    s += "\nFor more information, try '--help'.\n"
    sys.stderr.write(s)
    raise SystemExit(2)


def similarity(a, b):
    """Jaro similarity with a short prefix bonus, for spelling hints."""
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    d = max(len(a), len(b)) // 2 - 1
    d = max(0, d)
    ma, mb = [False] * len(a), [False] * len(b)
    for i, c in enumerate(a):
        for j in range(max(0, i-d), min(len(b), i+d+1)):
            if not mb[j] and c == b[j]:
                ma[i] = mb[j] = True
                break
    count = sum(ma)
    if not count:
        return 0.0
    aa, bb = [c for i,c in enumerate(a) if ma[i]], [c for i,c in enumerate(b) if mb[i]]
    tr = sum(c != d for c,d in zip(aa,bb))/2
    score = (count/len(a) + count/len(b) + (count-tr)/count)/3
    prefix=0
    for c,d in zip(a[:4], b[:4]):
        if c != d: break
        prefix+=1
    if score > .7: score += prefix * .1 * (1-score)
    return score


def suggestion(value, choices, noun):
    close = sorted((similarity(value,c),c) for c in choices if similarity(value,c) > .8)
    if not close:
        return None
    names=[c for _,c in close]
    if len(names)==1:
        return 'a similar ' + noun + " exists: '"+names[0]+"'"
    return 'some similar '+noun+'s exist: '+', '.join("'"+c+"'" for c in names)


def unknown_subcommand(word, context=''):
    choices = (list(THEME_ALIASES)+list(THEME_ALIASES.values())+['help']) if context=='theme' else (list(ALIASES)+list(ALIASES.values())+['help'])
    error("unrecognized subcommand '" + word + "'", context, suggestion(word, choices, 'subcommand'))


def parse_args(args):
    opts = {'v': 0}
    context = ''
    command = None
    theme = None
    priority = None
    endopts = False
    i=0
    while i < len(args):
        arg = args[i]
        i+=1
        if arg == '--' and not endopts:
            endopts=True
            continue
        if arg.startswith('-') and arg!='-' and not endopts:
            if arg.startswith('--'):
                flag, equal, attached = arg.partition('=')
                short=LONGS.get(flag)
                tokens=[(short, attached if equal else None, flag)]
            else:
                tokens=[]
                for k,ch in enumerate(arg[1:]):
                    tail=arg[k+2:]
                    if ch in OPTION_NAMES:
                        tokens.append((ch, tail.lstrip('=') if tail else None, '-'+ch))
                        break
                    tokens.append((ch,None,'-'+ch))
            for short, val, flag in tokens:
                allowed={'h'} if context else {'j','s','b','c','l','v','h','V'}
                if context=='import-journals':allowed.add('p')
                if short not in allowed:
                    tip=None
                    if context=='assign-priority' and priority is None:
                        tip=f"to pass '{flag}' as a value, use '-- {flag}'"
                    if flag.startswith('--') and not tip:
                        cand=[k for k,v in LONGS.items() if v in allowed]
                        tip=suggestion(flag,cand,'argument')
                    error(f"unexpected argument '{flag}' found",context,tip)
                if short=='h':
                    sys.stdout.write(help_text(context));raise SystemExit(0)
                if short=='V':
                    sys.stdout.write('tui-journal 0.16.1\n');raise SystemExit(0)
                if short=='v':
                    if val is not None:
                        error(f"unexpected value '{val}' for '--verbose...' found; no more were expected", '')
                    opts['v']=min(255,opts['v']+1);continue
                if short in opts:
                    error(f"the argument '{OPTION_NAMES[short]}' cannot be used multiple times", context)
                if val is None:
                    if i < len(args) and (not args[i].startswith('-') or args[i]=='-'):
                        val=args[i];i+=1
                if val is None or val=='':
                    msg=f"a value is required for '{OPTION_NAMES[short]}' but none was supplied"
                    if short=='b': msg+='\n  [possible values: json, sqlite]'
                    error(msg)
                if short=='b' and val not in ('json','sqlite'):
                    error(f"invalid value '{val}' for '{OPTION_NAMES[short]}'\n  [possible values: json, sqlite]",tip=suggestion(val,['json','sqlite'],'value'))
                opts[short]=val
            continue
        if not context:
            cmd=ALIASES.get(arg,arg)
            if cmd=='help':
                ctx=''
                for part in args[i:]:
                    if not ctx:
                        p=ALIASES.get(part,part)
                        if p not in list(DESCRIPTIONS)[:4]+['help']: unknown_subcommand(part)
                        ctx=p
                    elif ctx=='theme':
                        p=THEME_ALIASES.get(part,part)
                        if p not in list(THEME_ALIASES.values())+['help']: unknown_subcommand(part,'theme')
                        ctx+=' '+p
                    else:
                        error("unrecognized subcommand '"+part+"'",ctx)
                sys.stdout.write(help_text(ctx));raise SystemExit(0)
            if cmd not in ('print-config','import-journals','assign-priority','theme'):
                unknown_subcommand(arg)
            context=command=cmd
            endopts=False
        elif context=='theme':
            sub=THEME_ALIASES.get(arg,arg)
            if sub=='help':
                ctx='theme'
                for part in args[i:]:
                    p=THEME_ALIASES.get(part,part)
                    if p not in list(THEME_ALIASES.values())+['help']:unknown_subcommand(part,'theme')
                    ctx+=' '+p
                sys.stdout.write(help_text(ctx));raise SystemExit(0)
            if sub not in THEME_ALIASES.values():unknown_subcommand(arg,'theme')
            context='theme '+sub
            theme=sub
        elif context=='assign-priority' and priority is None:
            try:
                if not arg or arg.strip()!=arg or any(c not in '0123456789' for c in arg.lstrip('+-')) or len(arg.lstrip('+-'))==0:
                    raise ValueError('invalid digit found in string' if arg else 'cannot parse integer from empty string')
                val=int(arg)
                if not -(2**63)<=val<2**63:
                    raise ValueError('number too large to fit in target type' if val>=0 else 'number too small to fit in target type')
                if not 0<=val<=4294967295:
                    raise ValueError(f'{val} is not in 0..=4294967295')
                priority=val
            except ValueError as e:
                error(f"invalid value '{arg}' for '<PRIORITY>': {e}")
        else:
            error(f"unexpected argument '{arg}' found", context)
    if context=='theme':
        sys.stderr.write(help_text('theme'));raise SystemExit(2)
    if context=='import-journals' and 'p' not in opts:
        error('the following required arguments were not provided:\n  --path <FILE PATH>',context)
    if context=='assign-priority' and priority is None:
        error('the following required arguments were not provided:\n  <PRIORITY>',context)
    return opts, command, theme, priority
