        if arg == '--' and not endopts:
            endopts=True
            continue
        if arg.startswith('-') and arg!='-' and not endopts:
            if arg.startswith('--'):
                flag, equal, attached = arg.partition('=')
                short=LONGS.get(flag)
                tokens=[(short, attached if equal else None, flag)]
            else:
                tokens=[]
                for k,ch in enumerate(arg[1:]):
                    tail=arg[k+2:]
                    if ch in OPTION_NAMES:
