                        tip=f"to pass '{flag}' as a value, use '-- {flag}'"
                    if flag.startswith('--') and not tip:
                        cand=[k for k,v in LONGS.items() if v in allowed]
                        tip=suggestion(flag,cand,'argument')
                    error(f"unexpected argument '{flag}' found",context,tip)
                if short=='h':
                    sys.stdout.write(help_text(context));raise SystemExit(0)
                if short=='V':
                    sys.stdout.write('tui-journal 0.16.1\n');raise SystemExit(0)
                if short=='v':
                    if val is not None:
                        error(f"unexpected value '{val}' for '--verbose...' found; no more were expected", '')
                    opts['v']=min(255,opts['v']+1);continue
                if short in opts:
                    error(f"the argument '{OPTION_NAMES[short]}' cannot be used multiple times", context)
                if val is None:
                    if i < len(args) and (not args[i].startswith('-') or args[i]=='-'):
                        val=args[i];i+=1
                if val is None or val=='':
                    msg=f"a value is required for '{OPTION_NAMES[short]}' but none was supplied"
                    if short=='b': msg+='\n  [possible values: json, sqlite]'
                    error(msg)
                if short=='b' and val not in ('json','sqlite'):
                    error(f"invalid value '{val}' for '{OPTION_NAMES[short]}'\n  [possible values: json, sqlite]",tip=suggestion(val,['json','sqlite'],'value'))
                opts[short]=val
