def type_description(v):
    if type(v) is bool:return 'boolean `'+str(v).lower()+'`'
    if type(v) is int:return 'integer `'+str(v)+'`'
    if type(v) is float:return 'floating point `'+str(v)+'`'
    if type(v) is str:return 'string '+json.dumps(v,ensure_ascii=False)
    if isinstance(v,list):return 'sequence'
    if isinstance(v,dict):return 'map'
    return 'map'


def read_settings(custom=None):
    result=defaults()
    if custom is not None:
        if not os.path.exists(custom):raise AppError("Provided custom directory doesn't exit. Path: "+custom)
        path=os.path.join(custom,'config.toml') if os.path.isdir(custom) else custom
    else:path=os.path.join(config_dir(),'config.toml')
    if os.path.exists(path):
        try:
            with open(path,encoding='utf-8') as f:text=f.read()
        except OSError as e:raise AppError('Failed to read configuration file. Error infos: '+io_message(e))
        except UnicodeError:raise AppError('Failed to read configuration file. Error infos: stream did not contain valid UTF-8')
        try:
            doc=TomlDocument(text)
            def fail(key,msg):
                p,n=doc.spans.get(key,(0,1))
                raise TomlError(text,p,n,msg)
            def merge(dst,src,schema,path=()):
                for k,v in src.items():
                    if k not in schema:continue
                    kind=schema[k];kp=path+(k,)
                    if isinstance(kind,dict):
                        if not isinstance(v,dict):fail(kp,'invalid type: '+type_description(v)+', expected struct '+STRUCTS.get(k,k))
                        merge(dst[k],v,kind,kp)
                    elif isinstance(kind,tuple):
                        if isinstance(v,dict):
                            if len(v)!=1:fail(kp,'wanted exactly 1 element, more than 1 element')
                            v=next(iter(v))
                        if not isinstance(v,str):fail(kp,'wanted string or table')
                        if v not in kind:
                            expected='`'+kind[0]+'` or `'+kind[1]+'`' if len(kind)==2 else 'one of '+', '.join('`'+s+'`' for s in kind)
                            fail(kp,'unknown variant `'+v+'`, expected '+expected)
                        dst[k]=v
                    else:
                        valid=(type(v) is bool) if kind=='a boolean' else (type(v) is int and 0<=v<=2**64-1) if kind=='usize' else isinstance(v,str)
                        if not valid:
                            why='value' if type(v) is int and kind=='usize' else 'type'
                            fail(kp,'invalid '+why+': '+type_description(v)+', expected '+kind)
                        dst[k]=v
            merge(result,doc.data,SCHEMA)
        except TomlError as e:raise AppError('Failed to read configuration file. Error infos: '+str(e))
    return result


def cli_file_path(p):
    # Canonicalize the parent, creating it first even for read-only commands.
    p=p.rstrip('/') or '/'
    parent=os.path.dirname(p)
    if parent:
        try:os.makedirs(parent,exist_ok=True)
        except OSError as e:raise AppError(io_message(e))
    return os.path.realpath(p)


def apply_cli(settings,opts):
    if 'j' in opts:
        settings['json_backend']['file_path']=cli_file_path(opts['j']);settings['backend_type']='Json'
    if 's' in opts:
        settings['sqlite_backend']['file_path']=cli_file_path(opts['s']);settings['backend_type']='Sqlite'
    if 'b' in opts:settings['backend_type']=opts['b'].title()


def quote_string(s):
    if '\n' in s:
        q=json.dumps(s,ensure_ascii=False)[1:-1].replace('\\n','\n').replace('\\"','"')
        q=q.replace('"""','\\"\\"\\"')
        return '"""\n'+q+'"""'
    if '"' in s and "'" not in s and all(ord(c)>=32 and ord(c)!=127 for c in s):return "'"+s+"'"
    return json.dumps(s,ensure_ascii=False).replace('\\b','\\b').replace('\\f','\\f')


def toml_value(v):
    if type(v) is bool:return str(v).lower()
    if isinstance(v,str):return quote_string(v)
    if isinstance(v,int):
        if v>2**63-1:raise AppError("Settings couldn't be serialized\nError info: out-of-range value for u64 type")
        return str(v)
    return str(v)


def serialize_settings(s):
    parts=[]
    for key in SCHEMA:
        if isinstance(SCHEMA[key],dict):continue
        parts.append(key+' = '+toml_value(s[key]))
    parts.append('')
    for key,sub in SCHEMA.items():
        if not isinstance(sub,dict):continue
        parts.append('['+key+']')
        for name in sub:
            if name in s[key]:parts.append(name+' = '+toml_value(s[key][name]))
        parts.append('')
    return '\n'.join(parts)+'\n'
