"""TOML settings, path resolution, and serialization.

The small TOML reader retains value locations so errors can point to the input.
"""
import os
import re
import json
import datetime
from cli import home, xdg, config_dir


class AppError(Exception):
    pass


def io_message(e):
    if isinstance(e,OSError):
        return f'{e.strerror or os.strerror(e.errno)} (os error {e.errno})'
    return str(e)


class TomlError(Exception):
    def __init__(self,text,pos,length,message):
        self.text=text; self.pos=pos; self.length=length; self.message=message
    def __str__(self):
        pos=min(max(0,self.pos),len(self.text))
        line=self.text.count('\n',0,pos)+1
        before=self.text.rfind('\n',0,pos)+1
        col=pos-before+1
        end=self.text.find('\n',pos)
        if end<0:end=len(self.text)
        src=self.text[before:end].rstrip('\r')
        # Diagnostic gutters are padded to the width of the line number.
        gutter=' '*(len(str(line))+1)
        return (f'TOML parse error at line {line}, column {col}\n{gutter}|\n'
                f'{line} | {src}\n{gutter}| '+(' '*(col-1))+('^'*max(1,min(self.length,len(src)-col+1)))+'\n'+self.message+'\n')


class TomlDocument:
    def __init__(self,text):
        self.text=text
        self.i=0
        self.data={}
        self.spans={}
        self.current=()
        self.defined=set()
        self.parse()
    def fail(self,msg,pos=None,length=1):
        raise TomlError(self.text,self.i if pos is None else pos,length,msg)
    def spaces(self,newlines=False):
        while self.i<len(self.text):
            c=self.text[self.i]
            if c in (' \t\r\n' if newlines else ' \t\r'):
                self.i+=1
            elif c=='#' and newlines:
                e=self.text.find('\n',self.i);self.i=len(self.text) if e<0 else e+1
            else:break
    def string(self):
        q=self.text[self.i];start=self.i
        triple=self.text.startswith(q*3,self.i)
        self.i+=3 if triple else 1
        if triple and self.text[self.i:self.i+1]=='\n':self.i+=1
        out=''
        escapes={'b':'\b','t':'\t','n':'\n','f':'\f','r':'\r','"':'"','\\':'\\'}
        while self.i<len(self.text):
            if self.text.startswith(q*(3 if triple else 1),self.i):
                self.i+=3 if triple else 1
                if triple:
                    for _ in range(2):
                        if self.text[self.i:self.i+1]==q:out+=q;self.i+=1
                return out
            c=self.text[self.i];self.i+=1
            if c=='\n' and not triple:
                self.fail('invalid basic string',self.i-1)
            if c=='\\' and q=='"':
                if self.i>=len(self.text):break
                c=self.text[self.i];self.i+=1
                if c in escapes:out+=escapes[c]
                elif c in ('u','U'):
                    n=4 if c=='u' else 8
                    h=self.text[self.i:self.i+n]
                    try:out+=chr(int(h,16))
                    except (ValueError,OverflowError):self.fail('invalid unicode escape sequence',self.i,n)
                    self.i+=n
                elif triple and c in ' \t\r\n':
                    self.spaces(True)
                else:self.fail("invalid escape sequence\nexpected `b`, `f`, `n`, `r`, `t`, `u`, `U`, `\\`, `\"`",self.i-1)
            else:out+=c
        self.fail('invalid '+('literal' if q=="'" else 'basic')+' string\nexpected `'+q+'`',len(self.text))
    def key(self):
        self.spaces();parts=[];start=self.i
        while True:
            if self.text[self.i:self.i+1] in ('"',"'"):
                parts.append(self.string())
            else:
                m=re.match(r'[A-Za-z0-9_-]+',self.text[self.i:])
                if not m:self.fail('invalid key')
                parts.append(m.group());self.i+=len(m.group())
            self.spaces()
            if self.text[self.i:self.i+1]!='.':break
            self.i+=1;self.spaces()
        return tuple(parts),start
    def value(self,path):
        self.spaces();start=self.i;c=self.text[self.i:self.i+1]
        if not c:self.fail('invalid string\nexpected `"`, `\'`')
        if c in ('"',"'"):v=self.string()
        elif c=='[':
            self.i+=1;v=[];self.spaces(True)
            while self.text[self.i:self.i+1]!=']':
                v.append(self.value(path+(len(v),)))
                self.spaces(True)
                if self.text[self.i:self.i+1]==',':self.i+=1;self.spaces(True)
                elif self.text[self.i:self.i+1]!=']':self.fail('invalid array\nexpected `]`')
                if self.i>=len(self.text):self.fail('invalid array\nexpected `]`')
            self.i+=1
        elif c=='{':
            self.i+=1;v={};self.spaces()
            while self.text[self.i:self.i+1]!='}':
                keys,kstart=self.key()
                if self.text[self.i:self.i+1]!='=':self.fail('key with no value, expected `=`')
                self.i+=1
                value=self.value(path+keys)
                d=v
                for k in keys[:-1]:d=d.setdefault(k,{})
                if keys[-1] in d:self.fail('duplicate key',kstart,len('.'.join(keys)))
                d[keys[-1]]=value
                self.spaces()
                if self.text[self.i:self.i+1]==',':self.i+=1;self.spaces()
                elif self.text[self.i:self.i+1]!='}':self.fail('invalid inline table\nexpected `}`')
                if self.i>=len(self.text):self.fail('invalid inline table\nexpected `}`')
            self.i+=1
        else:
            m=re.match(r'[^\s,\]}#]+',self.text[self.i:])
            word=m.group() if m else ''
            if word in ('true','false'):v=word=='true'
            elif re.fullmatch(r'[+-]?(?:[0-9][0-9_]*|0[xX][0-9a-fA-F_]+|0[oO][0-7_]+|0[bB][01_]+)',word):
                try:v=int(word.replace('_',''),0 if re.match(r'0[xXoObB]',word) else 10)
                except ValueError:self.fail('invalid integer',start,len(word))
            elif re.fullmatch(r'[+-]?(?:(?:[0-9][0-9_]*)(?:\.[0-9_]+)?(?:[eE][+-]?[0-9_]+)?|inf|nan)',word):
                try:v=float(word.replace('_',''))
                except ValueError:self.fail('invalid floating-point number',start,len(word))
            elif re.match(r'\d{4}-\d\d-\d\d',word):
                try:v=datetime.datetime.fromisoformat(word.replace('Z','+00:00'))
                except ValueError:v=datetime.date.fromisoformat(word)
            else:
                self.fail('invalid string\nexpected `"`, `\'`',start)
            self.i+=len(word)
        self.spans[path]=(start,max(1,self.i-start))
        return v
    def parse(self):
        t=self.text
        if t.startswith('\ufeff'):self.i=1
        while self.i<len(t):
            self.spaces(True)
            if self.i>=len(t):break
            if t[self.i]=='[':
                start=self.i;array=t.startswith('[[',self.i)
                self.i+=2 if array else 1
                keys,kstart=self.key()
                close=']]' if array else ']'
                if not t.startswith(close,self.i):self.fail('invalid table header\nexpected `]`')
                self.i+=len(close)
                self.spans.setdefault(keys,(start,self.i-start))
                d=self.data
                for k in keys:
                    if k not in d:d[k]={}
                    if not isinstance(d[k],dict):self.fail('invalid table header\nduplicate key',start,self.i-start)
                    d=d[k]
                if keys in self.defined:self.fail('invalid table header\nduplicate key',start,self.i-start)
                self.defined.add(keys);self.current=keys
            else:
                keys,start=self.key()
                end=self.i
                if t[self.i:self.i+1]!='=':self.fail('key with no value, expected `=`')
                self.i+=1
                path=self.current+keys
                v=self.value(path)
                d=self.data
                for k in path[:-1]:
                    if k not in d:d[k]={}
                    if not isinstance(d[k],dict):self.fail('duplicate key',start,max(1,end-start))
                    d=d[k]
                if path[-1] in d:self.fail('duplicate key',start,len('.'.join(keys)))
                d[path[-1]]=v
            self.spaces()
            if self.text[self.i:self.i+1]=='#':
                e=t.find('\n',self.i);self.i=len(t) if e<0 else e
            if self.i<len(t) and t[self.i]!='\n':self.fail('expected newline, `#`')
            self.i+=1


def defaults():
    return {
        'backend_type':'Sqlite', 'scroll_per_page':5, 'sync_os_clipboard':False,
        'history_limit':10,'colored_tags':True,'datum_visibility':'show',
        'app_state_dir':os.path.join(xdg('XDG_STATE_HOME','.local/state'),'tui-journal'),
        'export':{'show_confirmation':True},
        'external_editor':{'auto_save':False,'temp_file_extension':'txt'},
        'json_backend':{'file_path':os.path.join(home(),'tui-journal','entries.json')},
        'sqlite_backend':{'file_path':os.path.join(home(),'tui-journal','entries.db')},
    }

SCHEMA = {
    'backend_type':('Json','Sqlite'), 'scroll_per_page':'usize','sync_os_clipboard':'a boolean',
    'history_limit':'usize','colored_tags':'a boolean','datum_visibility':('show','hide','empty_line'),
    'app_state_dir':'path string',
    'export':{'default_path':'path string','show_confirmation':'a boolean'},
    'external_editor':{'command':'a string','auto_save':'a boolean','temp_file_extension':'a string'},
    'json_backend':{'file_path':'path string'}, 'sqlite_backend':{'file_path':'path string'}
}
STRUCTS={'export':'ExportSettings','external_editor':'ExternalEditorSettings','json_backend':'JsonBackendSettings','sqlite_backend':'SqliteBackendSettings'}


def type_description(v):
    if type(v) is bool:return 'boolean `'+str(v).lower()+'`'
    if type(v) is int:return 'integer `'+str(v)+'`'
    if type(v) is float:return 'floating point `'+str(v)+'`'
    if type(v) is str:return 'string '+json.dumps(v,ensure_ascii=False)
    if isinstance(v,list):return 'sequence'
    if isinstance(v,dict):return 'map'
    return 'map'


def read_settings(custom=None):
    result=defaults()
    if custom is not None:
        if not os.path.exists(custom):raise AppError("Provided custom directory doesn't exit. Path: "+custom)
        path=os.path.join(custom,'config.toml') if os.path.isdir(custom) else custom
    else:path=os.path.join(config_dir(),'config.toml')
    if os.path.exists(path):
        try:
            with open(path,encoding='utf-8') as f:text=f.read()
        except OSError as e:raise AppError('Failed to read configuration file. Error infos: '+io_message(e))
        except UnicodeError:raise AppError('Failed to read configuration file. Error infos: stream did not contain valid UTF-8')
        try:
            doc=TomlDocument(text)
            def fail(key,msg):
                p,n=doc.spans.get(key,(0,1))
                raise TomlError(text,p,n,msg)
            def merge(dst,src,schema,path=()):
                for k,v in src.items():
                    if k not in schema:continue
                    kind=schema[k];kp=path+(k,)
                    if isinstance(kind,dict):
                        if not isinstance(v,dict):fail(kp,'invalid type: '+type_description(v)+', expected struct '+STRUCTS.get(k,k))
                        merge(dst[k],v,kind,kp)
                    elif isinstance(kind,tuple):
                        if isinstance(v,dict):
                            if len(v)!=1:fail(kp,'wanted exactly 1 element, more than 1 element')
                            v=next(iter(v))
                        if not isinstance(v,str):fail(kp,'wanted string or table')
                        if v not in kind:
                            expected='`'+kind[0]+'` or `'+kind[1]+'`' if len(kind)==2 else 'one of '+', '.join('`'+s+'`' for s in kind)
                            fail(kp,'unknown variant `'+v+'`, expected '+expected)
                        dst[k]=v
                    else:
                        valid=(type(v) is bool) if kind=='a boolean' else (type(v) is int and 0<=v<=2**64-1) if kind=='usize' else isinstance(v,str)
                        if not valid:
                            why='value' if type(v) is int and kind=='usize' else 'type'
                            fail(kp,'invalid '+why+': '+type_description(v)+', expected '+kind)
                        dst[k]=v
            merge(result,doc.data,SCHEMA)
        except TomlError as e:raise AppError('Failed to read configuration file. Error infos: '+str(e))
    return result


def cli_file_path(p):
    # Canonicalize the parent, creating it first even for read-only commands.
    p=p.rstrip('/') or '/'
    parent=os.path.dirname(p)
    if parent:
        try:os.makedirs(parent,exist_ok=True)
        except OSError as e:raise AppError(io_message(e))
    return os.path.realpath(p)


def apply_cli(settings,opts):
    if 'j' in opts:
        settings['json_backend']['file_path']=cli_file_path(opts['j']);settings['backend_type']='Json'
    if 's' in opts:
        settings['sqlite_backend']['file_path']=cli_file_path(opts['s']);settings['backend_type']='Sqlite'
    if 'b' in opts:settings['backend_type']=opts['b'].title()


def quote_string(s):
    if '\n' in s:
        q=json.dumps(s,ensure_ascii=False)[1:-1].replace('\\n','\n').replace('\\"','"')
        q=q.replace('"""','\\"\\"\\"')
        return '"""\n'+q+'"""'
    if '"' in s and "'" not in s and all(ord(c)>=32 and ord(c)!=127 for c in s):return "'"+s+"'"
    return json.dumps(s,ensure_ascii=False).replace('\\b','\\b').replace('\\f','\\f')


def toml_value(v):
    if type(v) is bool:return str(v).lower()
    if isinstance(v,str):return quote_string(v)
    if isinstance(v,int):
        if v>2**63-1:raise AppError("Settings couldn't be serialized\nError info: out-of-range value for u64 type")
        return str(v)
    return str(v)


def serialize_settings(s):
    parts=[]
    for key in SCHEMA:
        if isinstance(SCHEMA[key],dict):continue
        parts.append(key+' = '+toml_value(s[key]))
    parts.append('')
    for key,sub in SCHEMA.items():
        if not isinstance(sub,dict):continue
        parts.append('['+key+']')
        for name in sub:
            if name in s[key]:parts.append(name+' = '+toml_value(s[key][name]))
        parts.append('')
    return '\n'.join(parts)+'\n'
