import os
import select
import unicodedata
import time
import termios
import fcntl
import struct

RESET = (None,None,'',None)
COLORS={'Reset':None,'Black':0,'Red':1,'Green':2,'Yellow':3,'Blue':4,'Magenta':5,'Cyan':6,'Gray':7,'Grey':7,'DarkGray':8,
        'LightRed':9,'LightGreen':10,'LightYellow':11,'LightBlue':12,'LightMagenta':13,'LightCyan':14,'White':15}
MODIFIERS={'BOLD':1,'DIM':2,'ITALIC':3,'UNDERLINED':4,'SLOW_BLINK':5,'RAPID_BLINK':6,'REVERSED':7,'HIDDEN':8,'CROSSED_OUT':9}


