def normalize_date(value):
    if not isinstance(value,str):raise ValueError('expected an RFC 3339 formatted date and time string')
    if not re.match(r'^[-+]?\d{4,}-\d\d-\d\d[Tt ]\d\d:\d\d:\d\d',value):
        raise ValueError('premature end of input' if len(value)<=10 else 'input contains invalid characters')
    date=datetime.datetime.fromisoformat(value.replace('Z','+00:00').replace('z','+00:00'))
    if date.tzinfo is None:raise ValueError('premature end of input')
    return date.astimezone(datetime.timezone.utc).isoformat().replace('+00:00','Z')


def entry_value(obj,require_id=True):
    if isinstance(obj,list):
        names=(['id'] if require_id else [])+['date','title','content','tags','priority']
        obj=dict(zip(names,obj))
    if not isinstance(obj,dict):raise ValueError('expected struct Entry')
    for key in (['id'] if require_id else [])+['date','title','content','tags']:
        if key not in obj:raise ValueError('missing field `'+key+'`')
    if require_id and (type(obj['id']) is not int or obj['id']<0):raise ValueError('invalid id')
