    if not isinstance(obj['tags'],list) or not all(isinstance(s,str) for s in obj['tags']):raise ValueError('invalid tags')
    priority=obj.get('priority')
    if priority is not None and (type(priority) is not int or not 0<=priority<=4294967295):raise ValueError('invalid priority')
