            except ValueError:errors[2]='Priority must be a positive number'
        tags=[]
        if vals[3].strip():
            parts=vals[3].split(',')
            if vals[3].endswith(','):parts.pop()
            tags=[t.strip() for t in parts]
        return errors,dict(id=d['id'] or 0,date=date,title=vals[0],content='',tags=tags,priority=priority)
    def confirm_form(self):
        d=self.dialog;errors,value=self.form_errors(d);d['errors']=errors;d['touched'].update(range(4))
        if errors:return
        self.snapshot()
        if d['edit']:
            e=next((e for e in self.store.entries if e['id']==d['id']),None)
            if e is not None:
                value['content']=e['content'];e.update(value);rid=e['id']
            else:return
        else:rid=self.store.add(value)['id']
        self.dialog=None
        self.persist();self.refresh(rid)
    def open_filter(self):
        f=self.filters
        self.dialog={'type':'filter','fields':[TextInput(f[k]) for k in ('title','content','priority')],
                     'active':0,'tags':set(f['tags']),'tag_index':0,'logic':f['logic']}
    def open_sort(self):
        applied=self.sorter['criteria'][:]
        self.dialog={'type':'sort','active':0,'order':self.sorter['order'],'applied':applied,
                     'available':[k for k in ['Date','Title','Priority'] if k not in applied],'indexes':[0,0]}
    def open_fuzzy(self):
        self.dialog={'type':'fuzzy','field':TextInput(),'index':0,'results':[]}
    def fuzzy_update(self,d):
        query=d['field'].text.lower()
        found=[]
        if query:
            for e in self.shown():
                s=e['title'].lower();pos=-1;score=0
                for ch in query:
                    p=s.find(ch,pos+1)
                    if p<0:break
                    score+=p-pos-1;pos=p
                else:found.append((score,e))
        found.sort(key=lambda v:v[0])
        d['results']=[e for _,e in found];d['index']=min(d['index'],max(0,len(found)-1))
        if found:self.select(found[d['index']][1]['id'])
    def open_export(self):
        e=self.current()
        if self.multi:
            rows=[e for e in self.shown() if e['id'] in self.marked]
            if not rows:return
            name='tjournal_export.json'
        else:
            if not e:return
            rows=[e];name=e['title']+'.txt'
        root=self.settings['export'].get('default_path',os.getcwd())
        path=os.path.join(root,name)
        self.dialog={'type':'export','field':TextInput(path),'entries':rows,'multi':self.multi}
    def confirm_export(self):
        d=self.dialog;path=d['field'].text
        def write():
            self.dialog=None
            try:
                if d['multi']:self.store.export(path,d['entries'])
                else:
                    parent=os.path.dirname(path)
                    if parent:os.makedirs(parent,exist_ok=True)
                    with open(path,'w',encoding='utf-8') as f:f.write(self.buffer)
                if self.settings['export']['show_confirmation']:
                    self.tell('Journal(s)  exported to file '+path,'info')
            except (OSError,DataError) as e:self.tell('Error while exporting journals. Error: '+io_message(e))
        if os.path.exists(path):self.tell('File already exists. Do you want to overwrite it?','question',write,'yesno')
        else:write()
    def delete_selected(self):
        if self.multi:
            ids=self.marked.copy()
            if not ids:return
            text='Do you want to remove the selected journals?'
        else:
            if self.selected is None:return
            ids={self.selected};text='Do you want to remove the current journal?'
        def action():
            self.snapshot();self.store.entries=[e for e in self.store.entries if e['id'] not in ids]
            self.marked-=ids;self.persist();self.refresh()
        self.tell(text,'question',action,'yesno')
    def external_editor(self):
        if not self.current():return
        command=self.settings['external_editor'].get('command') or os.environ.get('VISUAL') or os.environ.get('EDITOR')
        if not command:self.tell('No external editor was found. Please set VISUAL or EDITOR environment variable.');return
        ext=self.settings['external_editor']['temp_file_extension']
        name=None
        try:
            with tempfile.NamedTemporaryFile(suffix='.'+ext,delete=False,mode='w',encoding='utf-8') as f:
                f.write(self.buffer);name=f.name
            self.term.leave()
            try:subprocess.run(shlex.split(command)+[name])
            finally:self.term.enter()
            with open(name,encoding='utf-8') as f:new=f.read()
            self.buffer=new;self.pos=0
            if self.settings['external_editor']['auto_save']:self.save_content()
        except OSError as e:self.tell('Error while opening external editor. Error: '+io_message(e))
        finally:
            if name:
                try:os.unlink(name)
                except OSError:pass

    def handle_message(self,k):
        m=self.message;b=m['buttons']
        if b=='ok':
            if k in ('Enter','o','O','Escape','C-c','q',' '):
                self.message=None
                if m['action']:m['action']()
        else:
            if k in ('y','Y'):
                self.message=None
                if m['action']:m['action']()
            elif k in ('n','N'):
                self.message=None
                if m['cancel']:m['cancel']()
            elif k in ('Escape','C-c','c','C'):
                self.message=None
    def handle_dialog(self,k):
        d=self.dialog;t=d['type']
        if t=='help':
            if k in ('Escape','C-c','q','?','Enter'):self.dialog=None
            elif k in ('Tab','Right','l'):d['tab']=(d['tab']+1)%3;d['scroll']=0
            elif k in ('BackTab','Left','h'):d['tab']=(d['tab']-1)%3;d['scroll']=0
            elif k in ('Down','j'):d['scroll']+=1
            elif k in ('Up','k'):d['scroll']=max(0,d['scroll']-1)
            elif k=='PageDown':d['scroll']+=5
            elif k=='PageUp':d['scroll']=max(0,d['scroll']-5)
            elif k=='Home':d['scroll']=0
            elif k=='End':d['scroll']=len(GLOBAL_KEYS)-1
            return
        if t=='tags':
            if k in ('Escape','C-c','q'):self.dialog=d['parent'];return
            tags=self.all_tags()
            if k in ('Down','j','C-n') and tags:d['index']=(d['index']+1)%len(tags)
            elif k in ('Up','k','C-p') and tags:d['index']=(d['index']-1)%len(tags)
            elif k==' ' and tags:
                tag=tags[d['index']]
                if tag in d['selected']:d['selected'].remove(tag)
                else:d['selected'].add(tag)
            elif k=='Enter':
                par=d['parent'];par['fields'][3]=TextInput(', '.join(t for t in tags if t in d['selected']));self.dialog=par
            return
        if k in ('Escape','C-c'):
            self.dialog=None;return
        if t=='form':
            if k=='Tab':
                d['touched'].add(d['active']);d['errors']=self.form_errors(d)[0];d['active']=(d['active']+1)%4
            elif k=='Enter':self.confirm_form()
            elif k in ('C-t','C-Space'):
                tags=set(t.strip() for t in d['fields'][3].text.split(',') if t.strip())
                self.dialog={'type':'tags','parent':d,'index':0,'selected':tags}
            else:
                if d['fields'][d['active']].key(k) and d['active'] in d['touched']:d['errors']=self.form_errors(d)[0]
        elif t=='filter':
            tags=self.all_tags()+['NO_TAGS']
            if k=='Tab':d['active']=(d['active']+1)%4
            elif k=='C-r':d['logic']='any' if d['logic']=='all' else 'all'
            elif k=='Enter':
                self.filters={key:d['fields'][i].text for i,key in enumerate(('title','content','priority'))}
                self.filters.update(tags=d['tags'],logic=d['logic']);self.dialog=None;self.refresh()
            elif d['active']==3:
                if k in ('Down','j','C-n'):d['tag_index']=(d['tag_index']+1)%len(tags)
                elif k in ('Up','k','C-p'):d['tag_index']=(d['tag_index']-1)%len(tags)
                elif k==' ':
                    tag=tags[d['tag_index']]
                    if tag in d['tags']:d['tags'].remove(tag)
                    else:d['tags'].add(tag)
            else:d['fields'][d['active']].key(k)
        elif t=='sort':
            if k=='Tab':d['active']=(d['active']+1)%3
            elif k in ('o','C-r') or (k==' ' and d['active']==0):d['order']='Ascending' if d['order']=='Descending' else 'Descending'
            elif k=='C-d':d.update(order='Descending',applied=['Date','Priority'],available=['Title'],indexes=[0,0])
            elif k=='Enter':
                self.sorter={'criteria':d['applied'][:],'order':d['order']};self.dialog=None;self.refresh()
            elif d['active'] in (1,2):
                j=d['active']-1;lst=d['available'] if j==0 else d['applied'];other=d['applied'] if j==0 else d['available']
                if k in ('Down','j') and lst:d['indexes'][j]=(d['indexes'][j]+1)%len(lst)
                elif k in ('Up','k') and lst:d['indexes'][j]=(d['indexes'][j]-1)%len(lst)
                elif k==' ' and lst:
                    other.append(lst.pop(min(d['indexes'][j],len(lst)-1)));d['indexes'][j]=min(d['indexes'][j],max(0,len(lst)-1))
        elif t=='fuzzy':
            if k=='Enter':self.dialog=None
            elif k in ('Down','C-n','Up','C-p') and d['results']:
                d['index']=(d['index']+(1 if k in ('Down','C-n') else -1))%len(d['results']);self.select(d['results'][d['index']]['id'])
            elif d['field'].key(k):d['index']=0;self.fuzzy_update(d)
        elif t=='export':
            if k=='Enter':self.confirm_export()
            else:d['field'].key(k)

    def editor_line_bounds(self):
        start=self.buffer.rfind('\n',0,self.pos)+1;end=self.buffer.find('\n',self.pos)
        return start,len(self.buffer) if end<0 else end
    def editor_move_line(self,d):
        start,end=self.editor_line_bounds();column=self.pos-start
        if d<0:
            if start==0:self.pos=0
            else:
                prev=self.buffer.rfind('\n',0,start-1)+1;self.pos=min(prev+column,start-1)
        else:
            if end==len(self.buffer):self.pos=len(self.buffer)
            else:
                nxt=self.buffer.find('\n',end+1)
                if nxt<0:nxt=len(self.buffer)
                self.pos=min(end+1+column,nxt)
    def editor_change(self,value,pos=None):
        if self.buffer!=value:
            self.editor_history.append((self.buffer,self.pos));self.editor_redo=[];self.buffer=value
        if pos is not None:self.pos=max(0,min(pos,len(self.buffer)))
    def editor_insert(self,s):self.editor_change(self.buffer[:self.pos]+s+self.buffer[self.pos:],self.pos+len(s))
    def editor_word(self,d):
        if d<0:
            m=re.search(r'\w+\W*$',self.buffer[:self.pos]);self.pos=m.start() if m else 0
        else:
            m=re.search(r'\w+\W*',self.buffer[self.pos:]);self.pos+=m.end() if m else len(self.buffer)-self.pos
    def editor_handle(self,k):
        if k in ('Escape','C-c'):
            self.mode='normal';self.visual_start=None;self.pending_motion='';return
        if k=='C-s':self.save_content();return
        if k=='C-q':
            self.tell('Do you want to discard all unsaved changes?','question',lambda:self.select(self.selected,True),'yesno');return
        if self.mode=='insert':
            if k=='Enter':self.editor_insert('\n')
            elif k=='Tab':self.editor_insert('\t')
            elif k in ('Left','C-b'):self.pos=max(0,self.pos-1)
            elif k in ('Right','C-f'):self.pos=min(len(self.buffer),self.pos+1)
            elif k in ('Home','C-a'):self.pos=self.editor_line_bounds()[0]
            elif k in ('End','C-e'):self.pos=self.editor_line_bounds()[1]
            elif k in ('C-Home',):self.pos=0
            elif k in ('C-End',):self.pos=len(self.buffer)
            elif k in ('Up','C-p'):self.editor_move_line(-1)
            elif k in ('Down','C-n'):self.editor_move_line(1)
            elif k in ('Backspace','C-h'):
                if self.pos:self.editor_change(self.buffer[:self.pos-1]+self.buffer[self.pos:],self.pos-1)
            elif k in ('Delete','C-d'):self.editor_change(self.buffer[:self.pos]+self.buffer[self.pos+1:])
            elif k=='C-k':
                end=self.editor_line_bounds()[1]
                if end==self.pos:end=min(len(self.buffer),end+1)
                self.clipboard=self.buffer[self.pos:end];self.editor_change(self.buffer[:self.pos]+self.buffer[end:])
            elif k=='C-u':
                start=self.editor_line_bounds()[0];self.editor_change(self.buffer[:start]+self.buffer[self.pos:],start)
            elif k in ('M-f','C-Right'):self.editor_word(1)
            elif k in ('M-b','C-Left'):self.editor_word(-1)
            elif k in ('C-w','M-Backspace'):
                end=self.pos;self.editor_word(-1);self.editor_change(self.buffer[:self.pos]+self.buffer[end:])
            elif k=='M-d':
                start=self.pos;self.editor_word(1);end=self.pos;self.editor_change(self.buffer[:start]+self.buffer[end:],start)
            elif len(k)==1 and ord(k)>=32:self.editor_insert(k)
            return
        # Normal/visual editing is Vim-like; application commands not consumed
        # below are handled by the main view.
        if self.pending_motion:
            prev=self.pending_motion;self.pending_motion=''
            if prev=='g' and k=='g':self.pos=0;return
            if prev in ('d','y','c'):
                start,end=self.editor_line_bounds()
                if k==prev:
                    end=min(len(self.buffer),end+1);self.clipboard=self.buffer[start:end]
                    if prev!='y':self.editor_change(self.buffer[:start]+self.buffer[end:],start)
                    if prev=='c':self.mode='insert'
                    return
                if k in ('w','$'):
                    start=self.pos
                    if k=='w':self.editor_word(1);end=self.pos
                    else:end=self.editor_line_bounds()[1]
                    self.clipboard=self.buffer[start:end]
                    if prev!='y':self.editor_change(self.buffer[:start]+self.buffer[end:],start)
                    else:self.pos=start
                    if prev=='c':self.mode='insert'
                    return
        if k in ('h','Left'):self.pos=max(0,self.pos-1)
        elif k in ('l','Right'):self.pos=min(len(self.buffer),self.pos+1)
        elif k in ('j','Down'):self.editor_move_line(1)
        elif k in ('k','Up'):self.editor_move_line(-1)
        elif k in ('0','Home'):self.pos=self.editor_line_bounds()[0]
        elif k=='^':
            start,end=self.editor_line_bounds();self.pos=start+len(self.buffer[start:end])-len(self.buffer[start:end].lstrip())
        elif k in ('$','End'):self.pos=self.editor_line_bounds()[1]
        elif k=='g':self.pending_motion='g'
        elif k=='G':self.pos=len(self.buffer)
        elif k in ('w','e'):self.editor_word(1)
        elif k=='b':self.editor_word(-1)
        elif k in ('i','I','a','A','o','O','Enter'):
            if not self.current():return
            if k=='I':self.pos=self.editor_line_bounds()[0]
            elif k=='a':self.pos=min(len(self.buffer),self.pos+1)
            elif k=='A':self.pos=self.editor_line_bounds()[1]
            elif k=='o':self.pos=self.editor_line_bounds()[1];self.editor_insert('\n')
            elif k=='O':self.pos=self.editor_line_bounds()[0];self.editor_insert('\n');self.pos-=1
            self.mode='insert'
        elif k=='v':
            if self.mode=='visual':self.mode='normal';self.visual_start=None
            else:self.mode='visual';self.visual_start=self.pos
        elif k in ('d','y','c'):
            if self.mode=='visual':
                a,b=sorted([self.pos,self.visual_start or 0]);b=min(len(self.buffer),b+1);self.clipboard=self.buffer[a:b]
                if k!='y':self.editor_change(self.buffer[:a]+self.buffer[b:],a)
                self.mode='insert' if k=='c' else 'normal';self.visual_start=None
            else:self.pending_motion=k
        elif k=='x':self.editor_change(self.buffer[:self.pos]+self.buffer[self.pos+1:])
        elif k=='D':
            end=self.editor_line_bounds()[1];self.editor_change(self.buffer[:self.pos]+self.buffer[end:])
        elif k in ('p','P'):self.editor_insert(self.clipboard)
        elif k=='u':
            if self.editor_history:self.editor_redo.append((self.buffer,self.pos));self.buffer,self.pos=self.editor_history.pop()
        elif k=='C-r':
            if self.editor_redo:self.editor_history.append((self.buffer,self.pos));self.buffer,self.pos=self.editor_redo.pop()
        else:self.handle_global(k)

    def handle_global(self,k):
        if k=='q':self.ask_unsaved(self.quit)
        elif k=='?':self.dialog={'type':'help','tab':2 if self.multi else (1 if self.focus=='editor' else 0),'scroll':0}
        elif k in ('Tab','BackTab','C-l','C-h'):
            self.focus='editor' if self.focus=='list' else 'list';self.mode='normal'
        elif k=='C-f':self.full_screen=not self.full_screen
        elif k in ('s','C-s'):self.save_content()
        elif k=='C-q':self.tell('Do you want to discard all unsaved changes?','question',lambda:self.select(self.selected,True),'yesno')
        elif k=='C-r':self.ask_unsaved(self.load)
        elif k in ('C-y','y'):self.external_editor()
        elif k=='>':self.open_export()
        elif k=='n':self.ask_unsaved(lambda:self.open_form())
        elif k=='e':self.ask_unsaved(lambda:self.open_form(True))
        elif k in ('d','Delete','C-d'):self.delete_selected()
        elif k in ('Enter',):
            if self.current():self.focus='editor';self.mode='insert'
        elif k in ('Down','j'):self.move_selection(1)
        elif k in ('Up','k'):self.move_selection(-1)
        elif k=='Home':self.move_selection(index=0)
        elif k=='End':self.move_selection(index=len(self.shown())-1)
        elif k=='PageDown':self.move_selection(self.settings['scroll_per_page'])
        elif k=='PageUp':self.move_selection(-self.settings['scroll_per_page'])
        elif k=='f':self.open_filter()
        elif k=='x':self.filters={'title':'','content':'','priority':'','tags':set(),'logic':'all'};self.refresh()
        elif k=='o':self.open_sort()
        elif k in ('a','F'):self.open_fuzzy()
        elif k=='v':self.multi=True;self.marked=set()
        elif k=='u':self.apply_history()
        elif k=='U':self.apply_history(True)
        elif k=='C-t':
            tags=self.all_tags()+['NO_TAGS'];self.tag_cycle=(self.tag_cycle+1)%(len(tags)+1)
            self.filters['tags']={tags[self.tag_cycle]} if self.tag_cycle<len(tags) else set();self.refresh()
    def handle(self,k):
        if k=='EOF':self.quit();return
        if self.message:self.handle_message(k);return
        if self.dialog:self.handle_dialog(k);return
        if self.multi:
            if k in ('q','v','Escape','C-c'):self.multi=False;self.marked=set()
            elif k in (' ','Enter') and self.selected is not None:
                if self.selected in self.marked:self.marked.remove(self.selected)
                else:self.marked.add(self.selected)
            elif k=='a':self.marked={e['id'] for e in self.shown()}
            elif k=='x':self.marked=set()
            elif k=='i':self.marked={e['id'] for e in self.shown()}-self.marked
            elif k in ('d','Delete'):self.delete_selected()
            elif k=='>':self.open_export()
            elif k in ('?','Down','j','Up','k','Home','End','PageUp','PageDown'):self.handle_global(k)
        elif self.focus=='editor':self.editor_handle(k)
        else:self.handle_global(k)

    def list_item(self,e,w):
        lines=[]
        # The title occupies one row. Dates/priorities use separate rows when
        # they will not fit side by side.
        lines.append((truncate(e['title'],w),'title'))
        try:
            dt=datetime.datetime.fromisoformat(e['date'].replace('Z','+00:00'));date=f'{dt.day},{dt.month},{dt.year}'
        except ValueError:date=e['date']
        priority='' if e['priority'] is None else 'Priority: '+str(e['priority'])
        datum=self.settings['datum_visibility']
        if datum=='show':
            if priority and width(date+' | '+priority)<=w:lines.append((date+' | '+priority,'date'))
            else:
                lines.append((date,'date'))
                if priority:lines.append((priority,'date'))
        elif datum=='empty_line':lines.append(('','date'))
        if e['tags']:
            for line in wrap(' | '.join(e['tags']),w):lines.append((line,'tags'))
        return lines
    def render_list(self,c,rect):
        x,y,w,h=rect
        title='Journals'
        if any(self.filters[k] for k in ('title','content','priority','tags')):title+=' - Filtered'
        if self.multi:title+=' - Multi-Select'
        bstyle=self.st('journals_list.block_multi_select' if self.multi else 'journals_list.block_active' if self.focus=='list' else 'journals_list.block_inactive')
        c.box(x,y,w,h,title,bstyle)
        rows=self.shown()
        if not rows:
            c.paragraph(x+1,y+2,w-2,max(0,h-3),"Use 'n' to create new entry",center=True)
            return
        idx=next((i for i,e in enumerate(rows) if e['id']==self.selected),0)
        items=[self.list_item(e,max(1,w-4)) for e in rows]
        if self.offset>idx:self.offset=idx
        while self.offset<idx and sum(len(z) for z in items[self.offset:idx+1])>h-2:self.offset+=1
        rowy=y+1
        for i in range(self.offset,len(rows)):
            if rowy>=y+h-1:break
            e=rows[i]
            selected=e['id']==self.selected
            marked=e['id'] in self.marked
            for li,(text,kind) in enumerate(items[i]):
                if rowy>=y+h-1:break
                prefix='> ' if selected and li==0 else '  '
                if kind=='title':
                    if self.multi:text=('* ' if marked else '  ')+text
                    st=self.st('journals_list.title_selected' if marked else 'journals_list.title_active' if self.focus=='list' else 'journals_list.title_inactive')
                    if selected:
                        st=self.st('journals_list.highlight_active' if self.focus=='list' else 'journals_list.highlight_inactive')
                        c.fill(x+1,rowy,w-2,1,st)
                elif kind=='date':st=self.st('journals_list.date_priority')
                else:st=self.st('journals_list.tags_default')
                c.put(x+1,rowy,prefix+text,st,w-2);rowy+=1
        counter=f'{idx+1}/{len(rows)}';c.put(x+w-1-width(counter),y+h-1,counter,bstyle)
    def render_editor(self,c,rect):
        x,y,w,h=rect
        active=self.focus=='editor'
        kind='block_'+(self.mode if self.mode in ('insert','visual') and active else 'normal_active' if active else 'normal_inactive')
        title='Content'
        if active:title+=' - '+self.mode.upper()
        if self.dirty:title+=' *'
        c.box(x,y,w,h,title,self.st('editor.'+kind))
        lines=self.buffer.split('\n')
        # Text editor preserves line structure and scrolls vertically with the
        # caret. Long lines are clipped horizontally rather than reflowed.
        row=self.buffer.count('\n',0,self.pos)
        start=self.buffer.rfind('\n',0,self.pos)+1;col=width(self.buffer[start:self.pos])
        if row<self.editor_scroll:self.editor_scroll=row
        if row>=self.editor_scroll+h-2:self.editor_scroll=max(0,row-(h-3))
        scrollx=max(0,col-(w-3)) if active else 0
        for j,line in enumerate(lines[self.editor_scroll:self.editor_scroll+max(0,h-2)]):
            c.put(x+1,y+1+j,line.expandtabs(4)[scrollx:],RESET,w-2)
        if active and self.current() and h>2 and w>2:
