def run(settings,opts,command,priority):
    term=Terminal()
    app=JournalApp(settings,opts,term)
    term.enter()
    try:
        app.load()
        if command=='assign-priority' and not app.message:
            for e in app.store.entries:
                if e['priority'] is None:e['priority']=priority
            app.persist();app.refresh()
        elif command=='import-journals' and not app.message:
            try:app.store.import_file(opts['p']);app.refresh()
            except DataError as e:app.tell(str(e))
        app.render();size=term.size()
        while app.running:
            key=term.read_key(.1)
            newsize=term.size()
            if key:
                app.handle(key)
                if app.running:app.render()
            elif newsize!=size:app.render()
            size=newsize
        app.save_state()
    finally:
        term.close()
    return 0
