class TextInput:
    def __init__(self,text='',end=False):
        self.text=str(text);self.pos=len(self.text) if end else 0;self.scroll=0
    def key(self,k):
        t=self.text;p=self.pos
        if k in ('Left','C-b'):self.pos=max(0,p-1)
        elif k in ('Right','C-f'):self.pos=min(len(t),p+1)
        elif k in ('Home','C-a'):self.pos=0
        elif k in ('End','C-e'):self.pos=len(t)
        elif k in ('Backspace','C-h'):
            if p:self.text=t[:p-1]+t[p:];self.pos-=1
        elif k in ('Delete','C-d'):self.text=t[:p]+t[p+1:]
        elif k=='C-k':self.text=t[:p]
        elif k in ('M-b','C-Left'):
            m=re.search(r'\w+\W*$',t[:p]);self.pos=m.start() if m else 0
        elif k in ('M-f','C-Right'):
            m=re.search(r'\w+\W*',t[p:]);self.pos=p+m.end() if m else len(t)
        elif k in ('C-w','M-Backspace'):
            m=re.search(r'\w+\W*$',t[:p]);start=m.start() if m else 0
            self.text=t[:start]+t[p:];self.pos=start
        elif k=='M-d':
            m=re.search(r'\w+\W*',t[p:]);end=p+m.end() if m else len(t)
            self.text=t[:p]+t[end:]
        elif len(k)==1 and ord(k)>=32:
            self.text=t[:p]+k+t[p:];self.pos+=1
        return self.text!=t
    def visible(self,n):
        if self.pos<self.scroll:self.scroll=self.pos
        if width(self.text[self.scroll:self.pos])>=n:
            while width(self.text[self.scroll:self.pos])>=max(1,n):self.scroll+=1
        return truncate(self.text[self.scroll:],n),width(self.text[self.scroll:self.pos])


