            else:d['field'].key(k)

    def editor_line_bounds(self):
        start=self.buffer.rfind('\n',0,self.pos)+1;end=self.buffer.find('\n',self.pos)
        return start,len(self.buffer) if end<0 else end
    def editor_move_line(self,d):
        start,end=self.editor_line_bounds();column=self.pos-start
        if d<0:
            if start==0:self.pos=0
            else:
                prev=self.buffer.rfind('\n',0,start-1)+1;self.pos=min(prev+column,start-1)
        else:
            if end==len(self.buffer):self.pos=len(self.buffer)
            else:
                nxt=self.buffer.find('\n',end+1)
                if nxt<0:nxt=len(self.buffer)
                self.pos=min(end+1+column,nxt)
    def editor_change(self,value,pos=None):
        if self.buffer!=value:
            self.editor_history.append((self.buffer,self.pos));self.editor_redo=[];self.buffer=value
        if pos is not None:self.pos=max(0,min(pos,len(self.buffer)))
    def editor_insert(self,s):self.editor_change(self.buffer[:self.pos]+s+self.buffer[self.pos:],self.pos+len(s))
    def editor_word(self,d):
        if d<0:
