        else:
            m=re.search(r'\w+\W*',self.buffer[self.pos:]);self.pos+=m.end() if m else len(self.buffer)-self.pos
    def editor_handle(self,k):
        if k in ('Escape','C-c'):
            self.mode='normal';self.visual_start=None;self.pending_motion='';return
        if k=='C-s':self.save_content();return
        if k=='C-q':
            self.tell('Do you want to discard all unsaved changes?','question',lambda:self.select(self.selected,True),'yesno');return
        if self.mode=='insert':
            if k=='Enter':self.editor_insert('\n')
            elif k=='Tab':self.editor_insert('\t')
            elif k in ('Left','C-b'):self.pos=max(0,self.pos-1)
            elif k in ('Right','C-f'):self.pos=min(len(self.buffer),self.pos+1)
            elif k in ('Home','C-a'):self.pos=self.editor_line_bounds()[0]
            elif k in ('End','C-e'):self.pos=self.editor_line_bounds()[1]
            elif k in ('C-Home',):self.pos=0
            elif k in ('C-End',):self.pos=len(self.buffer)
            elif k in ('Up','C-p'):self.editor_move_line(-1)
            elif k in ('Down','C-n'):self.editor_move_line(1)
            elif k in ('Backspace','C-h'):
                if self.pos:self.editor_change(self.buffer[:self.pos-1]+self.buffer[self.pos:],self.pos-1)
            elif k in ('Delete','C-d'):self.editor_change(self.buffer[:self.pos]+self.buffer[self.pos+1:])
            elif k=='C-k':
                end=self.editor_line_bounds()[1]
                if end==self.pos:end=min(len(self.buffer),end+1)
                self.clipboard=self.buffer[self.pos:end];self.editor_change(self.buffer[:self.pos]+self.buffer[end:])
            elif k=='C-u':
                start=self.editor_line_bounds()[0];self.editor_change(self.buffer[:start]+self.buffer[self.pos:],start)
            elif k in ('M-f','C-Right'):self.editor_word(1)
            elif k in ('M-b','C-Left'):self.editor_word(-1)
            elif k in ('C-w','M-Backspace'):
                end=self.pos;self.editor_word(-1);self.editor_change(self.buffer[:self.pos]+self.buffer[end:])
            elif k=='M-d':
                start=self.pos;self.editor_word(1);end=self.pos;self.editor_change(self.buffer[:start]+self.buffer[end:],start)
            elif len(k)==1 and ord(k)>=32:self.editor_insert(k)
            return
        # Normal/visual editing is Vim-like; application commands not consumed
        # below are handled by the main view.
        if self.pending_motion:
            prev=self.pending_motion;self.pending_motion=''
            if prev=='g' and k=='g':self.pos=0;return
            if prev in ('d','y','c'):
                start,end=self.editor_line_bounds()
                if k==prev:
                    end=min(len(self.buffer),end+1);self.clipboard=self.buffer[start:end]
                    if prev!='y':self.editor_change(self.buffer[:start]+self.buffer[end:],start)
                    if prev=='c':self.mode='insert'
