            elif k=='a':self.pos=min(len(self.buffer),self.pos+1)
            elif k=='A':self.pos=self.editor_line_bounds()[1]
            elif k=='o':self.pos=self.editor_line_bounds()[1];self.editor_insert('\n')
            elif k=='O':self.pos=self.editor_line_bounds()[0];self.editor_insert('\n');self.pos-=1
