        x,y,w,h=self.modal_rect(c,90,80)
        c.box(x,y,w,h,'Help',clear=True)
        c.box(x+2,y+1,w-4,3,'Tabs')
        labels=['Global','Editor','Multi-Select'];xx=x+4
        for i,label in enumerate(labels):
            c.put(xx,y+2,label,self.st('general.list_item_selected') if i==d['tab'] else RESET);xx+=len(label)
            if i<2:c.put(xx,y+2,' │ ');xx+=3
        tab=d['tab'];title=['Global Keybindings','Editor Keybindings','Multi-Select Mode Keybindings'][tab]
        bx=x+2;by=y+4;bw=w-4;bh=h-5
        c.box(bx,by,bw,bh,title)
        ix=bx+2;iy=by+1;iw=bw-4;ih=bh-2
        if tab==1:
            lines=[]
            for line in EDITOR_HELP.split('\n'):
                lines.extend(wrap(line,iw))
            off=min(d['scroll'],max(0,len(lines)-ih));d['scroll']=off
            for j,line in enumerate(lines[off:off+ih]):c.put(ix,iy+j,line,RESET,iw)
            return
        rows=GLOBAL_KEYS if tab==0 else MULTI_KEYS
        widths=[int(iw*.2),int(iw*.3),iw-int(iw*.2)-int(iw*.3)]
        rendered=[]
        for values in rows:
            cols=[wrap(value,max(1,n-1)) for value,n in zip(values,widths)]
            count=max(len(col) for col in cols)
            rendered.append((cols,count))
        positions=[ix,ix+widths[0],ix+widths[0]+widths[1]]
        for xpos,label in zip(positions,('Key','Command','Description')):c.put(xpos,iy,label,RESET,iw)
        off=min(d['scroll'],max(0,len(rows)-1))
        # When all rows fit, scrolling leaves the table at its first row.
        if sum(n for _,n in rendered)<=ih-2:off=0
        d['scroll']=off;yy=iy+2
        for cols,count in rendered[off:]:
            if yy>=iy+ih:break
            for xpos,col,n in zip(positions,cols,widths):
                for j,line in enumerate(col):
