    def render(self):
        w,h=self.term.size();c=Canvas(w,h);mainh=max(2,h-2)
        if self.full_screen:
            if self.focus=='list':self.render_list(c,(0,0,w,mainh))
            else:self.render_editor(c,(0,0,w,mainh))
        else:
            left=round(w*.3);self.render_list(c,(0,0,left,mainh));self.render_editor(c,(left,0,w-left,mainh))
        hint=MULTI_HINT if self.multi else INSERT_HINT if self.mode=='insert' and self.focus=='editor' else EDITOR_HINT if self.focus=='editor' else MAIN_HINT
        c.paragraph(0,h-2,w,2,hint)
